'use client';

import { useActionState } from 'react';

async function submitContactForm(prevState: any, formData: FormData) {
  'use server';

  const name = formData.get('name') as string;
  const email = formData.get('email') as string;
  const message = formData.get('message') as string;

  // JavaScript validation
  if (!name || name.trim() === '') {
    return { error: 'Name is required', success: false };
  }

  if (!email || email.trim() === '') {
    return { error: 'Email is required', success: false };
  }

  if (!message || message.trim() === '') {
    return { error: 'Message is required', success: false };
  }

  // Basic email format validation
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRegex.test(email)) {
    return { error: 'Please provide a valid email address', success: false };
  }

  // Simulate saving the contact message
  console.log('Contact message received:', { name, email, message });

  return {
    success: true,
    message: 'Thank you for your message! We will get back to you soon.'
  };
}

export default function ContactForm() {
  const [state, formAction, isPending] = useActionState(submitContactForm, null);

  return (
    <div>
      <h2>Contact Us</h2>
      <form action={formAction}>
        <div>
          <label htmlFor="name">Name:</label>
          <input
            id="name"
            name="name"
            type="text"
            placeholder="Your name"
            required
          />
        </div>

        <div>
          <label htmlFor="email">Email:</label>
          <input
            id="email"
            name="email"
            type="email"
            placeholder="your.email@example.com"
            required
          />
        </div>

        <div>
          <label htmlFor="message">Message:</label>
          <textarea
            id="message"
            name="message"
            placeholder="Your message"
            rows={5}
            required
          />
        </div>

        <button type="submit" disabled={isPending}>
          {isPending ? 'Sending...' : 'Send Message'}
        </button>

        {state?.error && (
          <div style={{ color: 'red', marginTop: '10px' }}>
            {state.error}
          </div>
        )}

        {state?.success && (
          <div style={{ color: 'green', marginTop: '10px' }}>
            {state.message}
          </div>
        )}
      </form>
    </div>
  );
}

